styles:
:root {
  color-scheme: dark;
  --bg: #070b12;
  --surface: rgba(255, 255, 255, 0.075);
  --surface-2: rgba(255, 255, 255, 0.055);
  --surface-3: rgba(255, 255, 255, 0.105);
  --text: #f4f7f8;
  --muted: #9aa7b2;
  --line: rgba(255, 255, 255, 0.12);
  --gold: #d7b24d;
  --gold-2: #f0ce73;
  --blue: #073b5a;
  --blue-2: #0b4f78;
  --danger: #f07171;
  --ok: #76d39b;
  --radius: 18px;
  --shadow: 0 28px 80px rgba(0, 0, 0, 0.34);
}

body.light {
  color-scheme: light;
  --bg: #f7f8fa;
  --surface: #ffffff;
  --surface-2: #eef3f7;
  --surface-3: #e6edf2;
  --text: #111315;
  --muted: #5d6872;
  --line: #d8e0e7;
  --gold: #94680a;
  --gold-2: #7b5608;
  --blue: #073b5a;
  --blue-2: #e7f0f6;
  --shadow: 0 14px 34px rgba(24, 35, 45, 0.12);
}

* {
  box-sizing: border-box;
}

html {
  background: var(--bg);
}

body {
  margin: 0;
  min-height: 100vh;
  overflow-x: hidden;
  background:
    radial-gradient(circle at 18% -10%, rgba(184, 138, 21, 0.24), transparent 34%),
    radial-gradient(circle at 100% 0%, rgba(29, 78, 216, 0.18), transparent 36%),
    var(--bg);
  color: var(--text);
  font-family: Inter, Segoe UI, Arial, sans-serif;
  font-size: 14px;
  line-height: 1.4;
}

.runtime-error {
  position: fixed;
  z-index: 9999;
  left: 12px;
  right: 12px;
  top: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(240, 113, 113, 0.7);
  border-radius: 8px;
  background: #2b0505;
  color: #fff;
  box-shadow: var(--shadow);
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

.app-shell {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 286px minmax(0, 1fr);
  grid-template-rows: auto 1fr;
  gap: 0;
}

.logged-out .app-shell {
  display: none;
}

.logged-in .login-screen {
  display: none;
}

.password-required .login-screen {
  display: grid;
}

.password-required .app-shell {
  display: none;
}

.login-screen {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 22px;
  background: var(--bg);
}

.login-card {
  width: min(440px, 100%);
  display: grid;
  gap: 18px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
  padding: 22px;
}

.login-logo {
  width: 100%;
  max-height: 120px;
  object-fit: contain;
}

.auth-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface-2);
}

.auth-tab {
  min-height: 42px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--muted);
  font-weight: 800;
}

.auth-tab.active {
  background: var(--gold);
  color: #111;
}

.link-btn {
  min-height: 34px;
  border: 0;
  background: transparent;
  color: var(--gold-2);
  padding: 4px 0;
  text-align: left;
  font-weight: 800;
}

.link-btn:hover {
  color: var(--gold);
  text-decoration: underline;
}

.auth-panel {
  display: none;
}

.auth-panel.active {
  display: grid;
}

.login-form {
  display: grid;
  gap: 10px;
}

.login-form.auth-panel {
  display: none;
}

.login-form.auth-panel.active {
  display: grid;
}

.login-message {
  min-height: 20px;
  color: var(--danger);
  margin: 0;
}

.auth-note,
.form-note {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.form-note {
  min-height: 18px;
}

.form-note.error,
.login-message.error {
  color: var(--danger);
}

.form-note.ok,
.login-message.ok {
  color: var(--ok);
}

.checkbox-row {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.checkbox-row input {
  width: 16px;
  height: 16px;
  accent-color: var(--gold);
}

.current-user {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.sync-status {
  min-width: max-content;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.sync-status[data-state="ok"] {
  color: var(--ok);
}

.sync-status[data-state="error"] {
  color: var(--danger);
}

.topbar {
  grid-column: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin: 16px 20px 0 8px;
  padding: 14px 18px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.04));
  border: 1px solid var(--line);
  border-radius: 26px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
  position: sticky;
  top: 0;
  z-index: 5;
}

.topbar > .brand {
  display: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 230px;
}

.brand-logo-wrap {
  width: 132px;
  height: 54px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid rgba(215, 178, 77, 0.45);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
  padding: 4px 8px;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.16);
}

.brand-logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
  border-radius: 0;
  display: block;
}

.brand strong,
.brand span {
  display: block;
}

.brand strong {
  color: var(--text);
  font-size: 17px;
}

.brand span {
  color: var(--muted);
  font-size: 12px;
}

.topbar-controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

.sidebar {
  grid-column: 1;
  grid-row: 1 / -1;
  position: sticky;
  top: 16px;
  height: calc(100vh - 32px);
  margin: 16px 0 16px 16px;
  background: rgba(7, 11, 18, 0.9);
  border: 1px solid var(--line);
  border-radius: 28px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
  padding: 14px;
  overflow: auto;
}

.sidebar-brand {
  display: grid;
  gap: 10px;
  margin-bottom: 16px;
  padding: 12px;
  border: 1px solid rgba(215, 178, 77, 0.2);
  border-radius: 22px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.03));
}

.sidebar-brand .brand-logo-wrap {
  width: 100%;
  height: 88px;
  border-radius: 18px;
}

.sidebar-brand small {
  color: var(--muted);
  font-weight: 800;
}

.nav {
  display: grid;
  gap: 6px;
}

.nav-track {
  display: grid;
  gap: 6px;
}

.nav-menu-wrap {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.nav-current {
  display: none;
}

.nav-arrow {
  display: none;
}

.nav-btn {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 11px;
  width: 100%;
  min-height: 46px;
  padding: 11px 12px;
  border: 1px solid transparent;
  border-radius: 16px;
  background: transparent;
  color: var(--muted);
  text-align: left;
}

.nav-btn i {
  width: 28px;
  height: 28px;
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--gold);
  font-style: normal;
  font-size: 12px;
  font-weight: 950;
}

.nav-btn span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.nav-btn.active,
.nav-btn:hover {
  color: var(--text);
  background: linear-gradient(135deg, rgba(184, 138, 21, 0.23), rgba(16, 35, 60, 0.44));
  border-color: var(--line);
}

.nav-btn.active::after {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gold);
}

.content {
  grid-column: 2;
  grid-row: 2;
  padding: 22px 20px 44px 8px;
  overflow: auto;
  min-width: 0;
}

.view {
  display: none;
  min-width: 0;
  max-width: 1320px;
  margin: 0 auto;
}

.view.active {
  display: block;
}

.view-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 18px;
  border: 1px solid rgba(215, 178, 77, 0.22);
  border-radius: 28px;
  background: linear-gradient(145deg, rgba(215, 178, 77, 0.17), rgba(255, 255, 255, 0.055));
  box-shadow: var(--shadow);
  padding: 20px;
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--gold-2);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: clamp(31px, 4vw, 52px);
  line-height: 1.1;
  letter-spacing: -0.03em;
}

h2 {
  font-size: 17px;
  margin-bottom: 14px;
}

.panel {
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.085), rgba(255, 255, 255, 0.04));
  border: 1px solid var(--line);
  border-radius: 24px;
  box-shadow: var(--shadow);
  padding: 16px;
  margin-bottom: 16px;
  min-width: 0;
}

.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.panel-head h2 {
  margin: 0;
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(160px, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

.kpi {
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.085), rgba(255, 255, 255, 0.04));
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 14px;
  min-height: 104px;
}

.kpi span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
}

.kpi strong {
  display: block;
  margin-top: 10px;
  font-size: 26px;
}

.kpi small {
  color: var(--muted);
}

.split-layout {
  display: grid;
  grid-template-columns: minmax(290px, 390px) minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.agenda-layout {
  grid-template-columns: minmax(280px, 340px) minmax(0, 1fr);
}

.nutrition-layout {
  display: grid;
  grid-template-columns: minmax(290px, 360px) minmax(330px, 1fr);
  gap: 16px;
  align-items: start;
}

.finance-layout {
  display: grid;
  grid-template-columns: minmax(280px, 360px) minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.finance-toolbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
}

.finance-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}

.finance-tabs .seg-btn {
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface-2);
}

.finance-panel {
  display: none;
}

.finance-panel.active {
  display: block;
}

.finance-kpis .kpi:nth-child(2) {
  border-color: rgba(34, 197, 94, 0.28);
}

.finance-kpis .kpi:nth-child(3) {
  border-color: rgba(215, 178, 77, 0.45);
}

.finance-overview-grid {
  display: grid;
  grid-template-columns: minmax(290px, 0.85fr) minmax(0, 1.15fr);
  gap: 16px;
  align-items: start;
}

.finance-card-list {
  display: grid;
  gap: 10px;
}

.finance-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface-2);
  padding: 12px;
}

.finance-card strong,
.finance-card span,
.finance-card small {
  display: block;
}

.finance-card strong {
  color: var(--text);
}

.finance-card span,
.finance-card small,
.finance-status-line {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.finance-card-actions {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) auto auto;
  gap: 8px;
  align-items: center;
}

.admin-card {
  grid-template-columns: minmax(0, 1fr) minmax(300px, auto);
}

.invoice-card {
  grid-template-columns: minmax(0, 1fr) minmax(240px, auto);
}

.invoice-actions {
  grid-template-columns: minmax(120px, 1fr) auto;
}

.status-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  padding: 5px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.status-badge.paid {
  border-color: rgba(34, 197, 94, 0.3);
  background: rgba(34, 197, 94, 0.12);
  color: var(--ok);
}

.status-badge.unpaid {
  border-color: rgba(215, 178, 77, 0.45);
  background: rgba(215, 178, 77, 0.13);
  color: var(--gold-2);
}

.finance-totals {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.schema-copy-panel,
.appointment-type-form,
.appointment-type-row {
  display: flex;
  align-items: end;
  gap: 10px;
  flex-wrap: wrap;
}

.schema-copy-panel {
  margin: 12px 0;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.appointment-type-manager {
  margin-top: 18px;
}

.appointment-type-form,
.appointment-type-row {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.appointment-type-list {
  display: grid;
  gap: 10px;
  margin-top: 12px;
}

.appointment-type-row input,
.appointment-type-form input {
  min-width: 120px;
}

.appointment-type-row input[type="color"],
.appointment-type-form input[type="color"] {
  min-width: 48px;
  width: 54px;
  padding: 4px;
}

.agenda-dashboard {
  display: grid;
  grid-template-columns: minmax(280px, 380px) minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.agenda-sidebar {
  display: grid;
  gap: 14px;
}

.agenda-calendar-panel {
  min-width: 0;
}

.form-step-label {
  margin: 12px 0 4px;
  color: var(--gold-2);
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.appointment-type-row {
  border-left: 6px solid var(--gold);
}

.appointment-type-row[draggable="true"] {
  cursor: grab;
}

.profile-edit-grid,
.profile-summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.profile-edit-grid {
  margin-top: 14px;
}

.profile-edit-grid .wide {
  grid-column: 1 / -1;
}

.profile-summary-grid div {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-2);
}

.profile-summary-grid span {
  display: block;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 800;
  text-transform: uppercase;
}

.profile-summary-grid strong {
  display: block;
  margin-top: 5px;
  color: var(--text);
  word-break: break-word;
}

@media (max-width: 980px) {
  .agenda-dashboard,
  .profile-edit-grid,
  .profile-summary-grid {
    grid-template-columns: 1fr;
  }

  .appointment-type-form,
  .appointment-type-row,
  .schema-copy-panel {
    align-items: stretch;
    flex-direction: column;
  }
}

.nutrition-plan-panel {
  min-height: 100%;
}

.trainer-tool {
  grid-column: span 1;
}

.client-food-panel {
  grid-column: 1 / -1;
}

.meal-plan-grid {
  display: grid;
  gap: 10px;
}

.meal-accordion {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
  overflow: hidden;
}

.meal-accordion-head {
  width: 100%;
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--text);
  padding: 12px 14px;
  text-align: left;
}

.meal-accordion-head span {
  color: var(--gold-2);
  font-size: 15px;
  font-weight: 900;
}

.meal-accordion-head small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  text-align: right;
}

.meal-accordion.open .meal-accordion-head {
  background: rgba(200, 147, 18, 0.12);
  border-bottom: 1px solid var(--line);
}

.meal-accordion-body {
  display: grid;
  gap: 10px;
  padding: 10px;
}

.meal-option-card {
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  padding: 12px;
}

.meal-option-main {
  display: grid;
  gap: 5px;
}

.meal-option-main span,
.meal-option-main p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.food-log-cards {
  display: grid;
  gap: 12px;
}

.food-log-day {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
  overflow: hidden;
}

.food-log-day-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px;
  border-bottom: 1px solid var(--line);
}

.food-log-day-head span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.food-log-list {
  display: grid;
  gap: 8px;
  padding: 10px;
}

.food-log-card {
  display: grid;
  grid-template-columns: minmax(160px, 1fr) minmax(220px, auto) auto;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  padding: 10px;
}

.food-log-card span {
  display: block;
  color: var(--muted);
  font-size: 12px;
}

.food-log-macros {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
}

.food-log-macros span {
  min-height: 26px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--text);
  padding: 3px 8px;
  font-weight: 800;
}

.food-log-week {
  display: grid;
  grid-template-columns: repeat(7, minmax(260px, 1fr));
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.food-log-day-column {
  min-width: 260px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
  overflow: hidden;
}

.food-log-column-head {
  display: grid;
  gap: 3px;
  padding: 12px;
  border-bottom: 1px solid var(--line);
}

.food-log-column-head strong {
  color: var(--gold-2);
}

.food-log-column-head span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.food-log-meal-cell {
  display: grid;
  gap: 8px;
  padding: 10px;
  border-bottom: 1px solid var(--line);
}

.food-log-meal-cell:last-child {
  border-bottom: 0;
}

.food-log-meal-cell > strong {
  color: var(--text);
}

.food-log-day-tabs {
  margin-top: 0;
}

.food-log-week.single-day {
  grid-template-columns: 1fr;
  overflow: visible;
}

.food-log-week.single-day .food-log-day-column {
  min-width: 0;
}

.food-log-week.single-day .food-log-column-head {
  grid-template-columns: minmax(0, 1fr);
}

.food-log-week.single-day .food-log-meal-cell {
  grid-template-columns: minmax(140px, 190px) minmax(180px, 1fr) minmax(160px, 220px);
  align-items: start;
}

.food-log-week.single-day .food-log-meal-cell textarea,
