  min-height: 34px;
  margin: 0;
  padding: 0;
  border-radius: 999px;
  font-size: 18px;
  line-height: 1;
}

.agenda-time-cell {
  min-height: 116px;
  padding: 12px 10px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.agenda-slot {
  position: relative;
  min-height: 116px;
  padding: 9px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent),
    rgba(255, 255, 255, 0.015);
  transition: background 0.18s ease, box-shadow 0.18s ease;
}

.agenda-slot:hover {
  background: rgba(200, 147, 18, 0.08);
  box-shadow: inset 0 0 0 1px rgba(200, 147, 18, 0.18);
}

.agenda-slot.has-events {
  background: rgba(255, 255, 255, 0.035);
}

.agenda-slot-add {
  position: absolute;
  top: 7px;
  right: 7px;
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--muted);
  font-weight: 900;
  opacity: 0;
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.agenda-slot:hover .agenda-slot-add,
.agenda-slot:focus-within .agenda-slot-add {
  opacity: 1;
}

.agenda-slot-add:hover {
  transform: scale(1.04);
  color: var(--gold-2);
}

.agenda-event {
  position: relative;
  display: grid;
  gap: 6px;
  margin-bottom: 8px;
  padding: 10px;
  border: 1px solid rgba(200, 147, 18, 0.28);
  border-left: 5px solid var(--event-color, #c89312);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(200, 147, 18, 0.12), transparent 72%),
    var(--surface);
  box-shadow: 0 12px 26px rgba(7, 12, 18, 0.08);
  cursor: grab;
}

.agenda-event:last-child {
  margin-bottom: 0;
}

.agenda-event-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.agenda-event-time {
  color: var(--gold-2);
  font-size: 12px;
  font-weight: 900;
}

.agenda-event-chip {
  max-width: 100%;
  overflow: hidden;
  padding: 3px 7px;
  border-radius: 999px;
  background: rgba(200, 147, 18, 0.14);
  color: var(--text);
  font-size: 10px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agenda-event strong {
  color: var(--text);
  font-size: 13px;
  line-height: 1.25;
}

.agenda-event small {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.agenda-event-actions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 5px;
  margin-top: 2px;
}

.agenda-event-actions button {
  min-height: 28px;
  padding: 5px 7px;
  font-size: 11px;
}

.appointment-type-card {
  display: grid;
  gap: 10px;
  align-items: stretch;
  border-left: 0;
  border-top: 4px solid var(--type-color, var(--gold));
}

.appointment-type-summary {
  display: flex;
  align-items: center;
  gap: 10px;
}

.type-swatch {
  width: 13px;
  height: 36px;
  border-radius: 999px;
  flex: 0 0 auto;
}

.appointment-type-summary strong {
  display: block;
  color: var(--text);
  font-size: 14px;
}

.appointment-type-summary small {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.appointment-type-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.appointment-type-fields input {
  min-width: 0;
}

.appointment-type-fields input[type="color"] {
  width: 100%;
  min-width: 0;
}

.appointment-type-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.client-appointment-date {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.trainer-calendar .appointment-card.compact-appointment {
  min-height: 0;
  display: grid;
  gap: 4px;
  margin: 0 0 8px;
  padding: 8px;
}

.trainer-calendar .appointment-card.compact-appointment:last-child {
  margin-bottom: 0;
}

.trainer-calendar .appointment-card.compact-appointment strong {
  margin: 0;
  color: var(--text);
  font-size: 12px;
}

.trainer-calendar .appointment-card.compact-appointment span {
  color: var(--muted);
  font-size: 12px;
}

.trainer-calendar .appointment-card.compact-appointment .appointment-actions {
  grid-template-columns: 1fr;
  gap: 4px;
  margin-top: 4px;
}

.trainer-calendar .appointment-card.compact-appointment .appointment-actions button {
  min-height: 30px;
  padding: 5px 7px;
  font-size: 11px;
}

.exercise-meta {
  color: var(--muted);
  font-size: 12px;
  margin-bottom: 10px;
}

.exercise-log {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.exercise-log label {
  display: grid;
  gap: 4px;
  color: var(--muted);
  font-size: 12px;
}

.exercise-log textarea {
  grid-column: 1 / -1;
  min-height: 58px;
}

.exercise-notes-field {
  grid-column: 1 / -1;
}

.exercise-notes-field textarea {
  margin-top: 4px;
  resize: vertical;
}

.training-session-list.exercise-row {
  display: grid;
  grid-auto-flow: row;
  grid-auto-columns: unset;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  overflow: visible;
  padding: 12px;
}

.training-session-list.exercise-row .training-exercise-card.exercise-card {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  display: grid;
  grid-template-columns: 116px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  margin: 0;
  padding: 12px;
}

.training-exercise-card .exercise-photo {
  align-self: start;
}

.training-exercise-card .exercise-card-main,
.training-exercise-card .exercise-title-row > div {
  min-width: 0;
}

.training-exercise-card .exercise-title-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
}

.training-exercise-card .exercise-target-grid {
  grid-template-columns: repeat(4, minmax(88px, 1fr));
}

.training-exercise-card .exercise-log {
  grid-template-columns: repeat(3, minmax(120px, 1fr));
  align-items: start;
}

.training-exercise-card .exercise-notes-field {
  grid-column: 1 / -1;
}

.training-exercise-card .mini-target input,
.training-exercise-card .exercise-log input,
.training-exercise-card .exercise-log textarea {
  min-width: 0;
}

.empty-mini {
  margin: 10px;
  color: var(--muted);
  font-size: 12px;
}

.macro-totals div,
.metric-tile {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 10px;
}

.metric-tile span,
.macro-totals span {
  display: block;
  color: var(--muted);
  font-size: 12px;
}

.metric-tile strong,
.macro-totals strong {
  display: block;
  font-size: 20px;
}

.week-grid,
.tracker-grid {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(135px, 1fr);
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.tracker-grid {
  grid-auto-columns: minmax(190px, 1fr);
}

.day-cell {
  display: grid;
  align-content: start;
  gap: 8px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 10px;
}

.day-cell label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
}

.day-cell input,
.day-cell select {
  margin-top: 6px;
}

.weight-grid .day-cell:last-child {
  display: grid;
  align-content: center;
  gap: 4px;
}

.water-panel {
  min-height: 320px;
  display: grid;
  align-content: start;
  justify-items: stretch;
  gap: 18px;
}

.water-display {
  width: 220px;
  height: 220px;
  border-radius: 50%;
  border: 10px solid var(--blue);
  display: grid;
  place-items: center;
  text-align: center;
  background: var(--surface-2);
  justify-self: center;
}

.water-display strong {
  display: block;
  font-size: 34px;
}

.water-display span {
  color: var(--muted);
}

.water-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.water-day-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(150px, 1fr));
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.water-day-card {
  min-width: 150px;
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
  padding: 12px;
}

.water-day-card strong {
  color: var(--gold-2);
}

.water-day-card label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
}

.water-day-card span {
  color: var(--muted);
  font-size: 12px;
}

.water-day-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.water-day-actions button {
  min-height: 34px;
  padding: 7px 8px;
  font-size: 12px;
}

.tracker-save-btn {
  width: 100%;
  min-height: 36px;
}

.save-feedback {
  min-height: 18px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.save-feedback.ok {
  color: var(--ok);
}

.tracker-overview-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: start;
  margin-bottom: 16px;
}

.tracker-overview-head h1 {
  margin: 0;
}

.tracker-client-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.tracker-input-card,
.tracker-week-block {
  display: grid;
  gap: 12px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--surface);
  box-shadow: var(--shadow);
  padding: 16px;
}

.tracker-input-card.wide {
  grid-column: 1 / -1;
}

.tracker-card-head,
.tracker-week-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.tracker-card-head h2,
.tracker-week-head h2 {
  margin: 0 0 4px;
}

.form-grid.compact {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.progress-photo-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.photo-url-field {
  border: 1px dashed var(--line);
  border-radius: 12px;
  padding: 10px;
  background: var(--surface-2);
}

.tracker-kpis {
  margin-bottom: 16px;
}

.tracker-week-stack {
  display: grid;
  gap: 16px;
}

.tracker-week-days {
  display: grid;
  grid-template-columns: repeat(7, minmax(128px, 1fr));
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.tracker-week-day {
  min-height: 100px;
  display: grid;
  align-content: space-between;
  gap: 8px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface-2);
  padding: 12px;
}

.tracker-week-day.today {
  border-color: var(--gold);
  background: color-mix(in srgb, var(--gold) 12%, var(--surface));
}

.tracker-week-day span,
.tracker-week-day small {
  color: var(--muted);
  font-size: 12px;
}

.tracker-week-day strong {
  color: var(--text);
  font-size: 20px;
}

.tracker-detail-table {
  display: grid;
  gap: 8px;
  overflow-x: auto;
}

.tracker-detail-row {
  display: grid;
  grid-template-columns: 130px repeat(7, minmax(92px, 1fr));
  min-width: 860px;
  gap: 8px;
}

.tracker-detail-row > div {
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text);
  padding: 9px;
  font-size: 12px;
}

.tracker-detail-row > div:first-child {
  color: var(--gold-2);
  font-weight: 900;
}

.tracker-action-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1.2fr;
  gap: 12px;
}

body.light .eyebrow,
body.light th,
body.light .water-day-card strong,
body.light .tracker-detail-row > div:first-child {
  color: #6f4d05;
}

body.light .topbar,
body.light .panel,
body.light .kpi,
body.light .tracker-input-card,
body.light .tracker-week-block,
body.light .tracker-week-day,
body.light .tracker-detail-row > div {
  background: #ffffff;
}

body.light .sidebar {
  background: rgba(255, 255, 255, 0.92);
}

body.light .nav-btn.active,
body.light .nav-btn:hover {
  color: var(--text);
  background: rgba(184, 138, 21, 0.16);
}

body.light .view-head {
  background: linear-gradient(145deg, rgba(184, 138, 21, 0.14), rgba(255, 255, 255, 0.96));
}

body.light .tracker-week-day.today {
  background: rgba(184, 138, 21, 0.14);
}

.save-feedback.error {
  color: var(--danger);
}

.empty-state {
  color: var(--muted);
  padding: 12px;
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

@media (max-width: 1120px) {
  .app-shell {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr;
  }

  .topbar {
    position: static;
    align-items: flex-start;
    flex-direction: column;
  }

  .topbar-controls {
    width: 100%;
    flex-wrap: wrap;
  }

  .sidebar {
    grid-row: 2;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .nav {
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  }

  .content {
    grid-column: 1;
    grid-row: 3;
  }

  .split-layout,
  .nutrition-layout,
  .finance-layout,
  .finance-totals,
  .finance-overview-grid,
  .summary-layout {
    grid-template-columns: 1fr;
  }

  .kpi-grid {
    grid-template-columns: repeat(2, minmax(150px, 1fr));
  }

  .inline-form,
  .recipe-form,
  .food-entry-form,
  .goal-form-grid,
  .training-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .training-builder {
    grid-template-columns: 180px minmax(0, 1fr);
  }

  .exercise-library-panel {
    grid-column: 1 / -1;
  }

  .exercise-library-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    max-height: none;
  }
}

@media (max-width: 680px) {
  .app-shell {
    display: block;
    min-height: 100dvh;
    padding-bottom: 84px;
  }

  .content {
    padding: 14px 12px 96px;
    overflow: visible;
  }

  .topbar {
    position: sticky;
    top: 0;
    z-index: 20;
    flex-direction: column;
    align-items: stretch;
    padding: 8px 10px;
    gap: 8px;
  }

  .topbar-controls {
    width: 100%;
    flex: 0 0 auto;
    justify-content: flex-end;
    gap: 6px;
  }

  .topbar-controls .field.compact {
    min-width: 126px;
    flex: 1 1 auto;
  }

  .current-user {
    display: none;
  }

  #logoutButton {
    min-height: 36px;
    padding: 7px 9px;
    font-size: 12px;
  }

  #themeToggle {
    width: 36px;
    min-height: 36px;
  }

  .sidebar {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 30;
    padding: 8px 10px calc(8px + env(safe-area-inset-bottom));
    border-right: 0;
    border-bottom: 0;
    border-top: 1px solid var(--line);
    background: rgba(11, 19, 27, 0.96);
    box-shadow: 0 -12px 34px rgba(0, 0, 0, 0.32);
    overflow: visible;
  }

  .nav {
    display: grid;
    grid-template-columns: 44px minmax(0, 1fr) 44px;
    align-items: center;
    gap: 8px;
    overflow: visible;
    padding-bottom: 0;
    position: relative;
  }

  .nav-menu-wrap {
    position: static;
    min-width: 0;
  }

  .nav-current {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    min-width: 0;
    min-height: 44px;
    padding: 9px 11px;
    border: 1px solid rgba(215, 178, 77, 0.7);
    border-radius: var(--radius);
    background: var(--surface-2);
    color: var(--text);
    font-size: 13px;
    font-weight: 900;
    text-align: center;
  }

  .nav-current span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .nav-current strong {
    color: var(--gold-2);
    font-size: 15px;
    line-height: 1;
    transition: transform 0.18s ease;
  }

  .nav.menu-open .nav-current strong {
    transform: rotate(180deg);
  }

  .nav-track {
    display: none;
  }

  .nav.menu-open .nav-track {
    position: fixed;
    left: 10px;
    right: 10px;
    bottom: calc(68px + env(safe-area-inset-bottom));
    z-index: 80;
    display: grid;
    gap: 6px;
    max-height: min(68vh, 430px);
    overflow-y: auto;
    padding: 8px;
    border: 1px solid var(--line);
    border-radius: var(--radius);
    background: var(--surface);
    box-shadow: 0 -16px 38px rgba(0, 0, 0, 0.36);
  }

  .nav-arrow {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    min-height: 44px;
    border: 1px solid rgba(215, 178, 77, 0.55);
    border-radius: 999px;
    background: var(--surface-2);
    color: var(--gold-2);
    font-size: 25px;
    font-weight: 900;
    line-height: 1;
  }

  .nav-btn {
    display: flex;
    width: 100%;
    justify-content: center;
    min-width: 0;
    min-height: 44px;
    padding: 9px 11px;
    font-size: 13px;
    font-weight: 900;
    text-align: center;
    white-space: normal;
  }

  .nav-btn.active {
    color: var(--text);
    background: rgba(200, 147, 18, 0.18);
    border-color: rgba(215, 178, 77, 0.9);
  }

  .nav-btn.active::after {
    display: none;
  }

  .view-head,
  .panel-head {
    align-items: stretch;
    flex-direction: column;
    gap: 10px;
  }

  .finance-toolbar,
  .finance-tabs {
    display: grid;
    grid-template-columns: 1fr;
  }

  .finance-card,
  .admin-card,
  .finance-card-actions {
    grid-template-columns: 1fr;
  }

  .brand {
    min-width: 0;
    flex: 1 1 auto;
    gap: 8px;
  }

  .brand-logo-wrap {
    width: 132px;
    height: 46px;
    padding: 3px 6px;
  }

  .brand strong {
    font-size: 14px;
  }

  .brand span {
    display: none;
  }

  .panel {
    padding: 12px;
    margin-bottom: 12px;
    box-shadow: none;
  }

  .kpi {
    min-height: 86px;
    padding: 12px;
  }

  .kpi strong {
    font-size: 21px;
  }

  .week-toolbar {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .week-toolbar strong {
    grid-column: 1 / -1;
    min-width: 0;
    order: -1;
  }

  .training-day {
    grid-template-rows: auto minmax(0, 1fr);
    min-height: 0;
  }

  .training-day-header {
    grid-template-columns: 1fr;
    align-items: stretch;
    padding: 10px 12px;
  }

  .training-builder {
    grid-template-columns: 1fr;
  }

  .training-day-tabs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .training-form,
  .library-controls,
  .exercise-target-grid,
  .exercise-log,
  .exercise-library-list {
    grid-template-columns: 1fr;
  }

  .training-form input[name="exercise"],
  .training-form input[name="image"],
  .training-form button {
    grid-column: 1 / -1;
  }

  .training-session-list.exercise-row .training-exercise-card.exercise-card,
  .training-exercise-card {
    grid-template-columns: 1fr;
  }

  .training-exercise-card .exercise-title-row,
  .training-exercise-card .exercise-target-grid,
  .training-exercise-card .exercise-log {
    grid-template-columns: 1fr;
  }

  .exercise-photo {
    width: 100%;
    height: 170px;
  }

  .exercise-title-row {
    align-items: stretch;
    flex-direction: column;
  }

  .exercise-row {
    grid-auto-columns: minmax(235px, 82vw);
  }

  .calendar-day {
    min-height: 320px;
  }

  .agenda-table-wrap {
    max-width: 100%;
  }

  .agenda-table {
    min-width: 840px;
  }

  .agenda-time-head,
  .agenda-time-cell {
    width: 72px;
  }

  .agenda-table th,
  .agenda-table td {
