/* Definitieve preview-overname: dezelfde premium structuur als Traineromgeving 2.0. */
html {
  scroll-behavior: smooth;
}

body {
  background:
    radial-gradient(circle at 20% -10%, rgba(184, 138, 21, 0.24), transparent 34%),
    radial-gradient(circle at 100% 0%, rgba(16, 35, 60, 0.72), transparent 36%),
    var(--bg);
}

body.light {
  --bg: #f5f2e9;
  --surface: rgba(255, 255, 255, 0.82);
  --surface-2: rgba(255, 255, 255, 0.72);
  --surface-3: #eef1f3;
  --text: #101417;
  --muted: #64748b;
  --line: rgba(15, 23, 42, 0.12);
  background:
    radial-gradient(circle at 20% -10%, rgba(184, 138, 21, 0.18), transparent 34%),
    radial-gradient(circle at 96% 8%, rgba(16, 35, 60, 0.16), transparent 36%),
    var(--bg);
}

.app-shell {
  grid-template-columns: 286px minmax(0, 1fr);
  grid-template-rows: auto 1fr;
}

.sidebar {
  top: 16px;
  height: calc(100vh - 32px);
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin: 16px 0 16px 16px;
  padding: 14px;
  border-radius: 28px;
  background: rgba(7, 11, 18, 0.9);
  backdrop-filter: blur(18px);
  box-shadow: var(--shadow);
}

body.light .sidebar,
body.light .topbar {
  background: rgba(245, 242, 233, 0.9);
}

.sidebar-brand {
  margin-bottom: 0;
  padding: 12px;
  border-radius: 22px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.025));
}

.sidebar-brand .brand-logo-wrap {
  height: auto;
  min-height: 84px;
  background: transparent;
}

.sidebar-brand .brand-logo {
  width: 170px;
  max-width: 100%;
  height: auto;
  object-fit: contain;
}

.nav {
  gap: 7px;
  overflow-y: auto;
  scrollbar-width: none;
  padding-right: 2px;
}

.nav::-webkit-scrollbar {
  display: none;
}

.nav-btn {
  min-height: 46px;
  border: 0;
  border-radius: 14px;
  color: var(--muted);
  background: transparent;
  font-weight: 850;
}

.nav-btn.active,
.nav-btn:hover {
  color: var(--text);
  background: linear-gradient(135deg, rgba(184, 138, 21, 0.22), rgba(16, 35, 60, 0.44));
}

.nav-btn i {
  width: 28px;
  height: 28px;
  display: inline-grid;
  place-items: center;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--gold-2);
  font-style: normal;
  font-size: 12px;
  font-weight: 950;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 8;
  display: grid;
  grid-template-columns: auto minmax(220px, 1fr) auto;
  gap: 18px;
  align-items: center;
  margin: 0;
  padding: 22px clamp(18px, 3vw, 34px) 18px 8px;
  border: 0;
  border-radius: 0;
  background: linear-gradient(180deg, rgba(7, 11, 18, 0.98) 65%, transparent);
  box-shadow: none;
}

.trainer-top-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 200px;
}

.trainer-top-brand img {
  width: 118px;
  height: auto;
  object-fit: contain;
}

.trainer-top-brand strong,
.trainer-top-brand span {
  display: block;
}

.trainer-top-brand span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.topbar-search {
  min-height: 54px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 0 16px;
  background: rgba(255, 255, 255, 0.06);
}

.topbar-search span {
  color: var(--gold-2);
  font-size: 12px;
  font-weight: 950;
  text-transform: uppercase;
}

.topbar-search input {
  width: 100%;
  min-height: auto;
  border: 0;
  outline: 0;
  color: var(--text);
  background: transparent;
}

.topbar-controls {
  justify-content: flex-end;
}

.content {
  padding: 0 clamp(18px, 3vw, 34px) 42px 8px;
}

.view {
  max-width: 1480px;
}

.view.active {
  animation: fmzRise 0.24s ease both;
}

@keyframes fmzRise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.view-head,
.tracker-overview-head,
.preview-hero-panel {
  border-color: rgba(215, 178, 77, 0.24);
  background: linear-gradient(145deg, rgba(215, 178, 77, 0.18), rgba(255, 255, 255, 0.055));
