}

.client-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 12px;
}

.client-preview-card.metric {
  display: grid;
  gap: 6px;
  align-content: start;
