/* APPFMZ presentation only. Keep app roles, forms and action handlers intact. */
body.trainer-mode {
  background: radial-gradient(circle at 20% -10%, #b88a153d, transparent 34%),
    radial-gradient(circle at 100% 0%, #1d4ed133, transparent 36%), var(--bg);
}
body.trainer-mode .app-shell { grid-template-columns: 224px minmax(0, 1fr); }
body.trainer-mode .content { padding: 16px clamp(14px, 2.5vw, 36px) 100px; }
body.trainer-mode .view { max-width: none; min-width: 0; }
