body.trainer-mode .nav { min-height: 0; overflow-y: auto; }
body.trainer-mode .nav-btn { min-height: 44px; white-space: normal; text-align: left; }
body.trainer-mode .nav-btn.active { background: var(--gold-2); color: #17120a; }
