body.trainer-mode .view-head h1 { font-size: clamp(1.65rem, 3vw, 2.2rem); overflow-wrap: anywhere; }
body.trainer-mode :is(.panel-head,.tracker-card-head,.tracker-week-head,.training-day-header,.schema-copy-panel) { flex-wrap: wrap; }
body.trainer-mode :is(.kpi-grid,.trainer-preview-grid,.client-grid) { grid-template-columns: repeat(auto-fit, minmax(min(240px, 100%), 1fr)); }
body.trainer-mode .table-wrap { max-width: 100%; overflow: auto; }
body.trainer-mode :is(.field,input,select,textarea) { max-width: 100%; }
body.trainer-mode :is(.training-session-area,.training-days,.training-day,.exercise-library-panel,.panel) { min-width: 0; }
body.trainer-mode :is(.training-form,.nutrition-form,.manual-exercise-form) { grid-template-columns: repeat(auto-fit,minmax(min(150px,100%),1fr)); }
body.trainer-mode .training-builder { grid-template-columns: minmax(0, 1fr) minmax(220px, 280px); }
body.trainer-mode .training-day-sidebar { grid-column: 1 / -1; }
