  function paymentLine(x){return `<div class="fmz-payment-summary ${x.corrected?'is-corrected':''}"><strong>${money(x.cents)} · ${x.corrected?'Gecorrigeerd':x.cents<0?'Terugbetaald':'Ontvangen'}</strong><p>Betaaldatum: ${esc(x.date)} · ${esc(x.account?.data.name||'Rekening onbekend')} (${x.account?.data.type==='cash'?'Kas':'Bank'})</p><small>Geregistreerd: ${esc(stamp(x.record.created_at))}</small>${btn('Naar Bank/Kas','finance-bank',x.bankId)}${x.corrected?info('Oorspronkelijke invoer bewaard; telt niet meer als actieve betaling.'):''}</div>`;}
  function invoiceSummary(id){const x=F.invoiceState(s(),id,h.today());if(!x)return'';return `<div class="fmz-invoice-totals"><span>Totaal <strong>${money(x.data.document.totalCents)}</strong></span><span>Ontvangen <strong>${money(x.received)}</strong></span><span>Nog open <strong>${money(x.outstanding)}</strong></span></div>`+info(`${x.late?'Te laat · ':''}${x.statusLabel}${x.corrected?' · correctiehistorie aanwezig':''}`)+(x.refunded?info('Terugbetaald: '+money(x.refunded)):'')+(x.active.length?x.active.map(paymentLine).join(''):info('Geen actieve betaalregistratie.'))+`<details><summary>Volledige betaal- en correctiehistorie (${x.history.length})</summary>${x.history.map(paymentLine).join('')||info('Nog geen betalingen.')}</details>`;}
  function invoiceRows(rows){return cards(rows.map(x=>card(x.number,info(x.data.document.customer.name)+info(`${x.date} · totaal ${money(x.data.document.totalCents)} · ontvangen ${money(x.paidCents)} · open ${money(x.outstanding)}`),btn('Factuur en betaalhistorie','detail',x.id)+(x.outstanding>0?btn('Betaling registreren','payment',x.id,'primary-btn'):''))));}
  function paymentRows(rows){return cards(rows.map(x=>card(get(x.invoiceId)?.number||'Factuur',paymentLine(x)+(x.net!==undefined?info(`Ontvangst excl. btw ${x.net===null?'Onbekend':money(x.net)} · btw-deel ${x.vat===null?'Onbekend':money(x.vat)}`):''),btn('Factuur en historie','detail',x.invoiceId))));}
  function overview(){const d=F.dashboard(s(),span(),h.today()),label=`${span().from} t/m ${span().to}`;return `<section class="acc-welcome"><div><p class="eyebrow">Je financiële overzicht</p><h2>Grip op je administratie.</h2><p>Volg facturen, geld op je rekening en het resultaat afzonderlijk.</p></div>${btn('Factuur maken','new-package','','primary-btn')}</section>`+h.periodControl()+panel('Facturen uit deze periode',info('Factuurdatum binnen '+label+'. Betaalstand t/m de laatste dag van deze periode; credit en annulering zijn verwerkt.')+tiles([metric('Totaal gefactureerd',money(d.invoiced),'Na credit en annulering','invoiced'),metric('Ontvangen op deze facturen',money(d.received),'Netto gekoppeld t/m periode-einde','cohort-received'),metric('Nog te ontvangen',money(d.outstanding),d.open.length+' facturen','outstanding'),metric('Achterstallig',money(d.overdue),'Vervaldatum verstreken op '+h.today(),'overdue'),metric('Betaalde facturen',d.paid.length,'Aantal','paid'),metric('Gedeeltelijk betaald',d.partial.length,'Aantal','partial'),metric('Openstaande facturen',d.open.length,'Inclusief deelbetalingen','open')]))+panel('Omzet, kosten en winst',tiles([metric('Omzet exclusief btw',money(d.p.revenue),'Geboekt in deze periode','revenue'),metric('Btw over verkopen',money(d.p.outputVAT),'Volgens bevestigde btw-methode','output-vat'),metric('Zakelijke kosten',money(d.p.cost),'Zonder aftrekbare btw','cost'),metric('Aftrekbare voorbelasting',money(d.p.inputVAT),'Btw op zakelijke kosten','input-vat'),metric('Winst vóór inkomstenbelasting',money(d.p.profit),'Omzet min zakelijke kosten','profit')])+info('Omzet is geen ontvangen geld. Een openstaande factuur kan al omzet zijn. Aftrekbare btw is geen kostenpost; niet-aftrekbare btw kan wel bij de kosten horen.'))+panel('Geld in en uit in deze periode',info('Dit volgt de werkelijke betaal-/boekdatum, ook als je de invoer later hebt geregistreerd. Eigen overboekingen en privébewegingen blijven zichtbaar.')+tiles([metric('Ontvangen geld',money(d.incoming),'Alle geregistreerde ontvangsten','incoming'),metric('Uitgegeven geld',money(d.outgoing),'Alle geregistreerde uitgaande mutaties','outgoing'),metric('Netto geldstroom',money(d.netflow),'Ontvangen min uitgegeven','netflow')])+cards(d.p.bank.filter(r=>!r.data.hidden).map(r=>card(r.data.name,info(r.known?'Administratieve stand t/m '+span().to+': '+money(r.cents):'Onbekend — gecontroleerde beginstand ontbreekt'),btn('Rekening en mutaties','finance-account',r.id)))))+panel('Nog open, inclusief eerdere perioden',invoiceRows(M.project(s()).invoices.filter(i=>i.outstanding>0).slice(0,5)))+panel('Recent geregistreerde factuurbetalingen',info('Onafhankelijk van de gekozen periode. Een vandaag ingevoerde betaling van september telt bij september.')+paymentRows(d.recent))+panel('Wat moet ik nog controleren?',h.signals(d.p)+btn('Bank/Kas controleren','show-checks')+btn('Btw controleren','finance-vat'));
  }
  function bankCard(r){return card(`${r.date} · ${money(r.cents)} · ${r.category}`,info(`${r.account} (${r.accountType==='cash'?'Kas':'Bank'}) · ${r.description}`)+info(r.source+(r.corrected?' · volledig tegengeboekt':''))+info('Geregistreerd: '+stamp(r.recordedAt))+(r.available?info('Nog te koppelen: '+money(r.available)):'')+`<details><summary>Effect en correctiehistorie</summary><p>Bank/Kas: ${money(r.cents)}${r.corrected?' (oorspronkelijke invoer; tegenboeking aanwezig)':''}. Omzet ${money(r.revenue)} · kosten ${money(r.expense)} · winst ${money(r.profit)} · berekende btw ${money(r.vatEffect)}.</p><p>Een factuurbetaling verlaagt alleen het openstaande bedrag. Bij het kasstelsel kan het moment van de ontvangst de btw bepalen. Een invoercorrectie is geen echte terugbetaling.</p>${r.relatedIds.map(id=>{const x=get(id),i=x?.kind==='invoice'?F.invoiceState(s(),id,h.today()):null;return i?info(`${x.number}: nu ${i.statusLabel} · ${money(i.outstanding)} open`):x?.kind==='vat_period'?info('Btw-periode '+x.data.from+' t/m '+x.data.to):'';}).join('')}${r.history.map(c=>info(`${stamp(c.created_at)} · ${c.data.reason}`)).join('')||info('Geen invoercorrecties op deze bankmutatie.')}</details>`,r.relatedIds.map(id=>{const x=get(id);return x?.kind==='vat_period'?btn('Btw '+x.data.from+' t/m '+x.data.to,'vat-detail',id):x?.kind==='invoice'?btn(x.number,'detail',id):x?btn(x.data.supplier||'Bron','detail',id):'';}).join('')+btn('Bron en boekingen','detail',r.id)+(r.vat.length?r.vat.map(v=>btn('Btw-koppeling corrigeren','vat-correct',v.id)).join(''):r.kind!=='correction'&&!r.corrected?btn('Corrigeren / Foutieve invoer herstellen','bank-repair',r.id):''));}
  function bankActivity(filters=h.bankFilters()){let f={...filters};if(f.amount?.trim())f.cents=M.cents(f.amount,true);const rows=F.filterBank(F.bankRows(s()),f);return panel('Mutaties · geld in en uit',`<div class="acc-form fmz-bank-filters">${input('bankQuery','Zoek klant, factuur of omschrijving',filters.query||'')}${input('bankFrom','Vanaf',filters.from||'','date')}${input('bankTo','Tot en met',filters.to||'','date')}${input('bankAmount','Exact bedrag (€)',filters.amount||'','text','inputmode="decimal"')}${select('bankCategory','Categorie',[['','Alle categorieën'],...Object.entries(F.categoryNames)],filters.category||'')}${select('bankAccount','Rekening',[['','Alle rekeningen'],...s().records.filter(r=>r.kind==='account').map(r=>[r.id,r.data.name])],filters.account||'')}${select('bankDirection','Geldrichting',[['','In en uit'],['in','Ontvangsten'],['out','Uitgaven']],filters.direction||'')}${select('bankType','Bank of Kas',[['','Bank en Kas'],['bank','Bank'],['cash','Kas']],filters.accountType||'')}${btn('Filters toepassen','finance-bank-filter')}${btn('Alle mutaties tonen','finance-bank-clear')}</div>`+info(`${rows.length} mutaties. Alleen een afschrift bevestigt wat werkelijk op de bank is gebeurd.`)+cards(rows.map(bankCard)));}
