  function outgoings(){const d=F.dashboard(s(),span(),h.today());return h.periodControl()+panel('Werkelijk geregistreerde uitgaven',info('Uitgaande bank- en kasmutaties volgens betaaldatum. Een kostenfactuur kan in een andere periode vallen.')+cards(d.flows.filter(r=>r.cents<0).map(bankCard)))+panel('Zakelijke kosten in deze periode',info('Kosten: '+money(d.p.cost)+' · aftrekbare btw: '+money(d.p.inputVAT))+info('Btw-betalingen en privéopnames staan hierboven apart en verlagen de winst niet.')+cards(s().records.filter(r=>r.kind==='expense'&&r.date>=span().from&&r.date<=span().to).map(r=>card(r.data.supplier,info(r.date+' · '+r.data.description)+info(`Bon incl. btw ${money(r.data.gross_cents)} · zakelijke kosten ${money(r.data.cost_cents??(r.data.business_cents-r.data.input_vat_cents))} · aftrekbare btw ${money(r.data.input_vat_cents)}`),btn('Bon, boekingen en historie','detail',r.id))))+btn('Kosten of bon toevoegen','finance-add-expense'))+panel('Kostenberekening inclusief correcties en afschrijvingen',ledger('expense'));}
  function profit(){const p=M.project(s(),span().from,span().to);return h.periodControl()+panel('Winst vóór inkomstenbelasting',tiles([metric('Omzet exclusief btw',money(p.revenue),'Geboekte opbrengsten','revenue'),metric('Zakelijke kosten',money(p.cost),'Zonder aftrekbare btw','cost'),metric('Winst',money(p.profit),'Omzet min kosten','profit')])+info(`${money(p.revenue)} − ${money(p.cost)} = ${money(p.profit)}.`)+info('Winst is niet je banksaldo. Btw-betalingen, privéopnames, privéstortingen en aflossing van een lening horen niet in deze berekening. Niet-aftrekbare btw kan wel bij kosten horen. Inkomstenbelasting is hier niet berekend.')+h.signals(p))+panel('Onderliggende omzet',ledger('income'))+panel('Onderliggende kosten',ledger('expense'));}
  function vatSources(rows){return cards(rows.map(r=>card(r.date+' · '+r.label,info('Omzet voor btw: '+money(r.revenue)+' · btw verkopen: '+money(r.output)+' · voorbelasting: '+money(r.input))+(r.correction?info('Correctie — oorspronkelijke bron blijft bewaard'):''),btn('Bron en boekingen','detail',r.id))));}
  function vatPeriod(r){return card(r.data.from+' t/m '+r.data.to,info(r.status)+info('Berekend nu '+money(r.current)+' · aangegeven '+(r.declared===null?'Nog niet vastgelegd':money(r.declared)))+info('Betaald '+money(r.paid)+' · terugontvangen '+money(r.refunded)+' · nog '+(r.remaining===null?'Onbekend':money(r.remaining)+' (negatief = teruggaaf)'))+(r.changed?info('De bronnen zijn veranderd sinds vastlegging. Controleer dit verschil; APPFMZ wijzigt geen ingediende aangifte.'):'')+(r.declared!==null?info('Verschil tussen aangegeven en nu berekend: '+money(r.declared-r.current)):''),btn('Periode, bronnen en historie','vat-detail',r.id)+btn(r.declared===null?'Concept / aangifte vastleggen':'Aangifteregistratie corrigeren','vat-period',r.id)+(r.declared!==null?btn('Btw-betaling registreren','vat-payment',r.id,'primary-btn')+btn('Btw-teruggaaf registreren','vat-refund',r.id):''));}
  function vatDetail(id){const r=F.vatPeriods(s()).find(x=>x.id===id);if(!r)return info('Periode ontbreekt.');return vatPeriod(r)+panel('Betaal- en correctiehistorie',cards(r.history.map(x=>card(x.date+' · '+money(Math.abs(x.data.signed_cents))+' · '+(x.data.signed_cents>0?'Betaald':'Teruggaaf'),info(get(x.data.account_id)?.data.name+' · kenmerk '+x.data.reference)+info('Geregistreerd '+stamp(x.created_at))+(x.status==='reversed'?info('Gecorrigeerd: '+get(x.data.correction_id)?.data.reason):''),btn('Naar Bank/Kas','finance-bank',x.data.bank_id)+(x.status==='posted'?btn('Verkeerde periode / foutieve invoer herstellen','vat-correct',x.id):'')))))+panel('Aangiftehistorie',info('APPFMZ registreert alleen jouw bevestiging. Het indienen en daadwerkelijk betalen gebeurt buiten de app.')+info('Aangiftedatum: '+(r.data.filed_date||'Niet vastgelegd'))+info(r.data.reason||'Geen verschiltoelichting')+cards((r.data.history||[]).map(x=>card(stamp(x.at),info('Vorige status '+x.status+' · aangegeven '+(x.previous.declared_cents===undefined?'Nog niet vastgelegd':money(x.previous.declared_cents)))+info(x.previous.reason||'')))))+panel('Huidige berekening',vatSources(r.projection.vat));}
  function vat(){const d=F.vatSummary(s(),span()),p=d.p;return h.periodControl()+info('Btw is geen omzet of winst. Dit is een controleoverzicht; APPFMZ dient geen aangifte in en maakt geen geld over.')+info('Bevestigde methode: '+(p.methods.map(x=>x==='cash'?'Kasstelsel':'Factuurstelsel').join(' / ')||'Onbekend'))+tiles([metric('Omzet voor btw',money(p.vat.reduce((n,x)=>n+x.revenue,0)),'Volgens btw-methode','vat-revenue'),metric('Btw over verkopen',money(p.outputVAT),'Facturen / ontvangsten','output-vat'),metric('Aftrekbare voorbelasting',money(p.inputVAT),'Zakelijke kosten','input-vat'),metric('Btw-correcties',money(d.corrections),'Al inbegrepen in de totalen','vat-corrections'),metric('Berekend te betalen',money(Math.max(d.calculated,0)),p.flags.length?'Niet volledig geregistreerd':'Controleer vóór aangifte','vat-calculated'),metric('Berekende teruggaaf',money(Math.max(-d.calculated,0)),p.flags.length?'Niet volledig geregistreerd':'Controleer vóór aangifte','vat-calculated'),metric('Betaald aan Belastingdienst',money(d.paid),'Aan deze aangifteperioden gekoppeld','vat-payments'),metric('Ontvangen van Belastingdienst',money(d.refunded),'Aan deze aangifteperioden gekoppeld','vat-payments'),metric('Nog te betalen / ontvangen',d.remaining===null?'Onbekend':money(d.remaining),d.covered?'Negatief = teruggaaf':'Niet alle aangiften vastgelegd','vat-payments')])+h.signals(p)+panel('Aangiften en betalingen',info('Berekend en werkelijk aangegeven kunnen verschillen, bijvoorbeeld door gecontroleerde afronding. Het verschil wordt zichtbaar bewaard; er wordt geen fictieve kostenboeking gemaakt.')+btn('Gekozen periode: concept / aangifte vastleggen','vat-period','','primary-btn')+btn('Btw-betaling registreren','vat-payment')+btn('Btw-teruggaaf registreren','vat-refund')+cards(d.periods.map(vatPeriod))+(d.overlap.length?info('De selectie doorsnijdt een vastgelegde aangifteperiode. Open de volledige periode voor het juiste betalingssaldo.')+cards(d.overlap.map(vatPeriod)):''))+panel('Alle vastgelegde btw-perioden',cards(F.vatPeriods(s()).slice().reverse().map(vatPeriod)))+btn('Btw-overzicht als PDF','report-vat')+panel('Herkomst van de berekening',vatSources(p.vat));}
  function drill(id){const d=F.dashboard(s(),span(),h.today()),v=F.vatSummary(s(),span());if(['invoiced','cohort-received','outstanding','overdue','paid','partial','open'].includes(id)){const rows={invoiced:d.invoices,'cohort-received':d.invoices,outstanding:d.open,overdue:d.late,paid:d.paid,partial:d.partial,open:d.open}[id];return info('Facturen uit '+span().from+' t/m '+span().to+'; betaalstand t/m periode-einde.')+invoiceRows(rows);}if(id==='revenue'||id==='cost')return ledger(id==='revenue'?'income':'expense');if(id==='profit')return profit();if(['incoming','outgoing','netflow'].includes(id))return cards(d.flows.filter(r=>id==='incoming'?r.cents>0:id==='outgoing'?r.cents<0:true).map(bankCard));if(id==='vat-payments')return info(v.covered?'Alle aangifteperioden in deze selectie zijn vastgelegd.':'Nog niet alle aangifteperioden in deze selectie zijn vastgelegd; het resterende saldo is onbekend.')+cards([...v.periods,...v.overlap].map(vatPeriod));return vatSources(v.p.vat.filter(r=>id==='output-vat'?r.output!==0:id==='input-vat'?r.input!==0:id==='vat-corrections'?r.correction:true));}
