 'use strict';const A=FMZAccountingModel,F=FMZFinanceModel,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=A.money;
 const input=(name,label,value='',type='text')=>`<label><span>${label}</span><input name="${name}" value="${esc(value)}" type="${type}" ${type==='text'&&/amount/.test(name)?'inputmode="decimal"':''}></label>`;
 const select=(name,label,opts,value='')=>`<label><span>${label}</span><select name="${name}">${opts.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
