 const check=(name,label,value=false)=>`<label class="fmz-repair-confirm"><input type="checkbox" name="${name}" ${value?'checked':''}> ${label}</label>`,decimal=c=>(c/100).toFixed(2).replace('.',',');
 function mount(root,host,state){
  const s=host.snapshot(),periods=F.vatPeriods(s),existing=periods.find(r=>r.id===state.periodId),action=state.action,source=s.records.find(r=>r.id===state.settlementId),span=existing?{from:existing.data.from,to:existing.data.to}:state.span;
  state.values||=action==='period'?{from:span.from,to:span.to,filed:existing?.status==='filed',declared_amount:existing?.declared===null||!existing?'':decimal(existing.declared),filed_date:existing?.data.filed_date||host.today(),reason:'',reviewed:false}:action==='correct'?{mode:'unlink',reason:''}:{period_id:state.periodId||'',direction:state.direction||'payment',amount:'',date:host.today(),account_id:'',reference:'',description:'',bank_id:'',difference_reason:'',distinct_receipt_reason:''};
  const v=state.values;let fields='';
