 function form(id,title,fields,label='Boeking opslaan'){return panel(title,`<form data-acc-form="${id}" class="acc-form" novalidate>${fields}<div class="full"><button class="primary-btn" type="submit">${label}</button><p data-form-status role="status"></p></div></form>`);}
 function chooseRecord(name,label,kind,predicate=()=>true){return select(name,label,[['','Kies…'],...list(kind).filter(predicate).map(r=>[r.id,r.number||r.data.description||r.data.name])]);}
 const finance=FMZFinanceUI.create({snapshot:()=>snapshot,range,periodControl,today,esc,btn,info,panel,cards,card,input,select,signals,bankFilters:()=>bankFilters});
 function periodControl(){const v=periodType==='custom'?date('periodFrom','Vanaf',customPeriod.from)+date('periodTo','Tot en met',customPeriod.to):periodType==='quarter'?select('periodValue','Kwartaal',[1,2,3,4].map(q=>[`${periodValue.slice(0,4)}-Q${q}`,`${periodValue.slice(0,4)} kwartaal ${q}`]),periodValue):input('periodValue',periodType==='year'?'Jaar':'Maand',periodValue,periodType==='year'?'number':'month');return `<div class="acc-period">${select('periodType','Periode',[['month','Maand'],['quarter','Kwartaal'],['year','Jaar'],['custom','Aangepaste periode']],periodType)}${v}${periodType==='quarter'?input('quarterYear','Jaar',periodValue.slice(0,4),'number'):''}${btn('Toepassen','period-filter')}</div>`;}
 function range(){if(periodType==='custom'){const from=M.date(customPeriod.from),to=M.date(customPeriod.to);if(from>to)throw Error('De einddatum ligt vóór de begindatum.');return{from,to};}return M.period(periodType,periodValue);}
 function signals(p){return p.flags.length?`<aside class="acc-notice"><strong>Nog te controleren</strong><ul>${p.flags.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></aside>`:'<p>Technische aansluiting gecontroleerd. Het btw-overzicht blijft voorbereidend.</p>';}
 function salesHTML(){
  const p=M.project(snapshot),matches=r=>{const i=p.invoices.find(x=>x.id===r.id);return salesFilter==='all'||salesFilter==='partial'&&i?.statusLabel==='Gedeeltelijk betaald'||salesFilter==='corrected'&&FMZFinanceModel.invoiceState(snapshot,r.id,today())?.corrected||salesFilter==='open'&&i?.outstanding>0||salesFilter==='late'&&i?.outstanding>0&&i?.data.document.dueDate<today()||salesFilter==='draft'&&r.status==='draft'||salesFilter==='cancelled'&&i?.cancelled||salesFilter==='credited'&&(r.parent_id||i?.credits<0)||salesFilter==='paid'&&i?.statusLabel==='Betaald'||salesFilter==='posted'&&r.status==='posted'&&!r.parent_id&&!i?.cancelled&&i?.credits===0;};
  return btn('Pakketfactuur: concept openen','new-package','','primary-btn')+' '+btn('Vrije factuur: concept openen','new-invoice')+select('salesStatus','Facturen tonen',[['all','Alle facturen'],['open','Openstaand'],['partial','Gedeeltelijk betaald'],['late','Te laat'],['corrected','Gecorrigeerd'],['draft','Concept'],['posted','Definitief'],['paid','Betaald'],['cancelled','Geannuleerd'],['credited','Gecrediteerd']],salesFilter)+cards(list('invoice').filter(matches).slice().reverse().map(r=>{
   const d=r.data.document,i=p.invoices.find(x=>x.id===r.id),cancelled=!!r.data.cancellation_id;
   const links=list('invoice').filter(x=>x.parent_id===r.id&&x.status==='posted').map(x=>info('Credit: '+x.number+' · '+M.money(x.data.document.totalCents))+btn('Credit bekijken','detail',x.id)).join('');
   const periodInfo=(d?.billing||r.data.billing);
   const correction=r.parent_id?info('Credit op '+(get(r.parent_id)?.number||'')):cancelled?info('Geannuleerd: '+r.data.cancellation_reason):'';
   const actions=r.status==='draft'?btn('Concept openen / bewerken','invoice',r.id)+btn('Concept verwijderen','draft-delete',r.id):(i?.outstanding>0&&!r.parent_id&&!cancelled?btn('Betaling registreren','payment',r.id,'primary-btn'):'')+btn('PDF openen','invoice-open',r.id)+btn('PDF downloaden','invoice-pdf',r.id)+btn('Delen','invoice-share',r.id)+(!r.parent_id&&!cancelled?btn('Factuur annuleren','invoice-cancel',r.id)+btn('Creditfactuur maken','credit',r.id):'')+btn('Betalingen bekijken / corrigeren','detail',r.id);
   return card(r.number||'Concept — nog geen factuur',info(d?.customer.name||r.data.customer?.name)+info(d?.description||r.data.description)+info(d?`${M.money(d.totalCents)} · ${r.parent_id?'Creditfactuur':i?.statusLabel}${i?' · resterend '+M.money(i.outstanding):''}`:'Alleen een concept; geen omzetboeking')+(periodInfo?info(FMZBillingPeriods.label(periodInfo.cycle)+' · '+FMZBillingPeriods.display(periodInfo.start)+' t/m '+FMZBillingPeriods.display(periodInfo.end)):'' )+correction+links+finance.invoiceSummary(r.id),actions);
  }))+legacyHTML();
 }

