 async function upload(file,meta){assertOwner();const gen=epoch,bytes=new Uint8Array(await file.arrayBuffer()),sha=await M.hash(bytes),mime=file.type||(/\.csv$/i.test(file.name)?'text/csv':'application/octet-stream');const reservationKey=JSON.stringify([sha,meta]);let stateFile=uploadStates.get(reservationKey);if(!stateFile){stateFile={id:uid()};uploadStates.set(reservationKey,stateFile);}
