 async function openInvoiceChooser(){allowed();const selected=client();show('Pakketfactuur: periode kiezen',`<form class="acc-form" data-billing-invoice>${select('client_id','Klant',state.clients.map(c=>[c.id,c.name]),selected?.id)}${field('at_date','Datum binnen de te factureren serviceperiode',today(),'date')}<div class="full" data-period-choice></div><div class="full acc-actions"><button class="primary-btn" type="submit">Concept openen</button><button class="secondary-btn" type="button" data-edit-agreement>Klantafspraak beheren</button></div></form>`);
