 async function rpc(name,args={}){const generation=authGeneration;let timer;try{const result=await Promise.race([supabaseClient.rpc(name,args),new Promise((_,reject)=>timer=setTimeout(()=>reject(new Error('Geen serverbevestiging. Je invoer blijft hier staan; probeer opnieuw.')),20000))]);if(generation!==authGeneration||!onlineReady)throw new Error('Je sessie is verlopen. Log opnieuw in.');if(result.error){if(result.error.code==='28000')lockOnlineSession();throw result.error;}return result.data;}finally{clearTimeout(timer);}}
