 }
 function calendar(rows){const r=M.range(view,date);if(view==='list')return list(rows);if(view==='month'){const start=M.week(r.start);return `<div class="ag-month">${['ma','di','wo','do','vr','za','zo'].map(d=>`<strong>${d}</strong>`).join('')}${Array.from({length:42},(_,i)=>{const d=M.addDays(start,i),n=items().filter(a=>a.date===d);return `<button type="button" data-ag-day="${d}" class="ag-month-day ${d===M.today()?'is-today':''} ${d.slice(0,7)!==date.slice(0,7)?'outside':''}" aria-label="${E(M.label(d))}: ${n.length} afspraken"><strong>${Number(d.slice(-2))}</strong>${n.length?`<span>${n.length} afspraak${n.length===1?'':'en'}</span><small>${E(n[0].time||'')} ${E(n[0].type||'Afspraak')}</small>`:''}</button>`;}).join('')}</div>`;}
