 function render(){const root=Q('#agendaRoot');if(!root)return;if(!ensure()){root.replaceChildren();return;}const r=M.range(view,date),rows=items().filter(a=>a.date>=r.start&&a.date<r.end);root.innerHTML=`<div class="ag-heading"><div><p class="eyebrow">Planning · Amsterdam</p><h1>Agenda</h1><p>Je afspraken, overzichtelijk op één plek.</p></div><div class="ag-actions"><button class="secondary-btn ag-tools-toggle" data-ag-action="tools" aria-expanded="${document.body.classList.contains('agenda-tools-open')}" type="button">Appbediening</button><button class="secondary-btn" data-ag-action="messages" type="button">Meldingen${data?.inbox?.filter(i=>!i.read_at).length?' · '+data.inbox.filter(i=>!i.read_at).length:''}</button>${isTrainer()?'<button class="primary-btn" data-ag-action="new" type="button">Nieuwe afspraak</button>':''}</div></div><div class="ag-toolbar"><div class="ag-actions"><button class="secondary-btn" data-ag-move="-1" aria-label="Vorige periode" type="button">‹</button><button class="secondary-btn" data-ag-action="today" type="button">Vandaag</button><button class="secondary-btn" data-ag-move="1" aria-label="Volgende periode" type="button">›</button><label class="ag-date"><span class="sr-only">Gekozen datum</span><input type="date" value="${date}" data-ag-date></label></div><h2>${E(view==='week'?`${M.label(r.start,{day:'numeric',month:'short'})} – ${M.label(M.addDays(r.end,-1),{day:'numeric',month:'short',year:'numeric'})}`:M.label(date,view==='day'?{weekday:'long',day:'numeric',month:'long'}:{month:'long',year:'numeric'}))}</h2><div class="ag-view-switch" aria-label="Agendaweergave">${[['day','Dag'],['week','Week'],['month','Maand'],['list','Lijst']].map(([id,label])=>`<button type="button" data-ag-view="${id}" aria-pressed="${id===view}">${label}</button>`).join('')}</div></div><div class="ag-status" role="status">${E(error||(!data?'Agenda laden…':`${rows.length} afspraak${rows.length===1?'':'en'} in deze periode`))} <button class="text-btn" data-ag-act