 function openEdit(key=null,options={}){if(!isTrainer())return;if(pending){editForm();return;}if(dirty&&draft&&key!==draft.key){if(!confirm('Er staat nog een niet-opgeslagen afspraak. Dit concept verwerpen?'))return;pending=null;}const a=key?byKey(key):null;if(key&&!a)return;draft=a?JSON.parse(JSON.stringify(a)):{date:options.date||date,time:options.time||'09:00',duration:60,type:'Personal training',location:'',notes:'',participants:[{id:client()?.id}],trainerReminder:data?.preferences?.reminder_minutes??''};if(!a&&options.typeId){const t=appointmentTypeById(options.typeId);if(t)Object.assign(draft,{type:t.name,duration:t.duration||60,location:t.location||'',color:t.color,appointmentTypeId:t.id});}dirty=false;pending=null;editForm();}
