 async function command(action,payload,target){
  if(busy)return null;
  if(pending&&(pending.action!==action||JSON.stringify(pending.payload)!==JSON.stringify(payload))){if(target)target.textContent='Er wacht nog een eerder verzoek op bevestiging. Hervat dat verzoek en probeer opnieuw.';return null;}
  busy=true;const who=owner,generation=authGeneration;
  if(!pending)pending={action,payload,id:crypto.randomUUID()};const request=pending;
  if(target)target.textContent='Opslaan…';
  document.querySelectorAll('#agDialog button,#agEdit input,#agEdit select,#agEdit textarea').forEach(b=>b.disabled=true);
  try{
   const r=await rpc('fmz_agenda_command',{action:request.action,payload:request.payload,request_id:request.id});
   if(who!==owner||generation!==authGeneration)return null;
   pending=null;if(action==='create'||action==='edit')dirty=false;if(target)target.textContent='Opgeslagen';await refresh();return r;
  }catch(e){
   if(who===owner&&generation===authGeneration){
