    if(target)target.textContent=`Niet opgeslagen — ${e.code==='PT409'?'de afspraak is elders gewijzigd. Je invoer blijft staan. Haal de actuele afspraak op en vergelijk.':e.message||'opnieuw proberen'}`;
   }return null;
  }finally{
   if(generation===authGeneration){busy=false;document.querySelectorAll('#agDialog button').forEach(b=>b.disabled=false);document.querySelectorAll('#agEdit input,#agEdit select,#agEdit textarea').forEach(b=>b.disabled=!!pending);render();}
