 document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;const v=b.dataset;if(v.agAction||Object.keys(v).some(k=>k.startsWith('ag'))){event.preventDefault();if(!ensure())return;}
  if(v.agView){view=v.agView;render();}if(v.agMove){date=view==='month'||view==='list'?M.addMonths(date,Number(v.agMove)):M.addDays(date,Number(v.agMove)*(view==='week'?7:1));render();}if(v.agDay){date=v.agDay;view='day';render();}if(v.agDetail)details(v.agDetail);if(v.agEdit)openEdit(v.agEdit);if(v.agNewDate)openEdit(null,{date:v.agNewDate,time:v.agNewTime});
