}

function monthLabel(key) {
  if (!/^\d{4}-\d{2}$/.test(key)) return "-";
  const date = new Date(`${key}-01T12:00:00`);
  return date.toLocaleDateString("nl-NL", { month: "long", year: "numeric" });
