          <td>${appt ? `${escapeHTML(appt.date)} ${escapeHTML(appt.time)}` : "-"}</td>
        </tr>
      `;
    })
    .join("");
  $("#memberTable").innerHTML = rows || `<tr><td colspan="8">${state.clients.length ? "Geen resultaten." : "Nog geen clienten gekoppeld. Voeg eerst een client toe."}</td></tr>`;

  return selected;
}

