    if (!hasSelectedClient(selected) || !item) return;
    selected.trainingPlan.push({
      id: `training-${Date.now()}${Math.random().toString(16).slice(2)}`,
      day: state.ui.trainingDay || "Maandag",
      exercise: item.name,
      group: item.group,
      equipment: item.equipment,
      image: item.image,
      sets: 3,
      reps: "8-10",
      targetWeight: "",
      tempo: "",
      rest: "90s",
      actualSets: "",
      actualReps: "",
      actualWeight: "",
      notes: "",
